from pinecone import Pinecone

pc = Pinecone(api_key="YOUR_API_KEY")
index = pc.Index("loan-docs")

def search(user, vector, k=10):
    groups = [f"{user.tenant_id}:{g}" for g in user.groups]
    return index.query(namespace=user.tenant_id, vector=vector, top_k=k,
                       filter={"acl": {"$in": groups}}, include_metadata=True)

def offboard(tenant_id: str):
    index.delete(delete_all=True, namespace=tenant_id)   # the whole client, at once
    print(f"erased namespace {tenant_id}")

